package br.com.tapeteskalke.repository; import br.com.tapeteskalke.entity.Usuario; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface UsuarioRepository extends JpaRepository<Usuario,String> { interface Sessao { String getRole(); long getVersao(); } Optional<Usuario> findByEmailIgnoreCaseAndAtivoTrue(String email); boolean existsByEmailIgnoreCase(String email); @Query("select u.cargo.codigo as role, u.sessaoVersao as versao from Usuario u where u.id=:id and u.ativo=true") Optional<Sessao> activeSession(@Param("id")String id); @Modifying(clearAutomatically=true) @Query("update Usuario u set u.sessaoVersao=u.sessaoVersao+1 where u.id=:id") int revokeSessions(@Param("id")String id); @Query("select u from Usuario u join fetch u.cargo order by u.nome") List<Usuario> listWithCargo(); @Query("select count(u) from Usuario u where u.ativo=true and u.cargo.codigo='DONO'") long countActiveOwners(); }
